.manuscript-comment-card__close:hover {
  color: var(--color-ink);
}
.manuscript-comment-card__body {
  min-height: 0;
  overflow-y: auto;
  padding: 1rem;
}
.manuscript-comment-card__body > * + * {
  margin-top: 0.75rem;
}
.manuscript-comment-card__quote {
  padding: 0.75rem;
  border: 1px solid
    color-mix(in srgb, var(--comment-color) 34%, var(--color-paper-3));
  background: color-mix(
    in srgb,
    var(--comment-color) 6%,
    var(--color-paper-soft)
  );
  color: var(--color-ink-light);
  font-family: var(--font-serif);
  font-size: 0.8125rem;
  font-style: italic;
  line-height: 1.5;
}
.manuscript-comment-card__composer {
  padding-top: 0.75rem;
  border-top: 1px dashed var(--color-paper-3);
}
.manuscript-comment-card__textarea {
  width: 100%;
  min-height: 5.5rem;
  resize: vertical;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.8125rem;
  line-height: 1.5;
}
.manuscript-comment-card__textarea::placeholder {
  color: var(--color-ink-light);
}
.manuscript-comment-card__textarea:focus {
  border-color: var(--comment-color);
  outline: 2px solid color-mix(in srgb, var(--comment-color) 22%, transparent);
  outline-offset: 1px;
}
.manuscript-comment-card__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: 0.5rem;
}
.manuscript-comment-card__actions > span {
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
}

@media (max-width: 520px) {
  .manuscript-comment-card {
    left: 0.5rem !important;
    right: 0.5rem;
    bottom: 0.5rem !important;
    top: auto !important;
    width: auto !important;
    max-height: 70vh;
  }
}

/* Comment: marginalia highlight */
.twyne-editor .ProseMirror .comment-mark {
  background-color: color-mix(
    in srgb,
    var(--color-writer-note) 18%,
    transparent
    animation: none;
  }
}

.persona-note-card {
  position: fixed;
  z-index: var(--z-dropdown);
  width: min(20.5rem, calc(100vw - 1rem));
  padding: 0.85rem 1rem 1rem;
  background: var(--color-paper-soft);
  border: 1px solid
    color-mix(in srgb, var(--note-color) 45%, var(--color-paper-3));
  border-radius: 2px;
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
    0 18px 36px -20px color-mix(in srgb, var(--shade) 50%, transparent);
  animation: persona-note-pop 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes persona-note-pop {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .twyne-persona-note.is-flashing {
    animation: none;
    background: color-mix(in srgb, var(--note-color) 30%, transparent);
  }
  .persona-note-card {
    animation: none;
  }
}

/* ── Mark anchor chip ──
   A small dot rendered at the end of every contiguous run of three
   "comment-like" marks by the `MarkAnchorWidgets` ProseMirror plugin.
   Click it to open the matching popover without disturbing the caret
   in the marked text. The chip is the only hit target for these marks
   — hovering the marked text triggers the hover preview, not a chip
   click. */
.twyne-mark-anchor {
  color: var(--color-ink-light);
  font: italic 0.78rem/1.45 var(--font-serif);
}

/* A persona note wears the shared comment-card layout; the older
   stand-alone note card's padding and paper would frame it as a card
   inside a card. */
.persona-note-card.manuscript-comment-card,
.suggestion-card.manuscript-comment-card {
  padding: 0;
  background: var(--color-paper);
  border-color: var(--comment-color);
}

/* A conversation opened in the margin takes its card's place: the card
   steps aside and the thread unfolds from the same top edge, in the same
   accent, so it reads as the card opening rather than a second card. */
.flow-card.is-unfolded {
  visibility: hidden;
  pointer-events: none;
}
.manuscript-comment-card.is-in-margin {
  border-width: 1px;
  border-color: var(--color-paper-3);
  border-top: 3px solid var(--comment-color);
  border-radius: 2px;
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 18px 32px -18px rgb(0 0 0 / 0.45);
  transform-origin: top center;
  animation: margin-unfold 180ms ease-out;
  transition:
    top 160ms ease-out,
    left 160ms ease-out;
}
@keyframes margin-unfold {
  from {
    opacity: 0.4;
    transform: scaleY(0.94);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .flow-edge,
  .flow-card__gather.is-arming::after,
  [data-flow] .flow-surface > *,
  [data-flow] .in-flow-rails,
  [data-flow] .twyne-toolbar,
  [data-flow] .editor-desk-controls,
  [data-flow] .editor-workspace-shell > aside {
    animation: none;
    transition: none;
  }
  .flow-card,
  .flow-overlay__line,
  .flow-work__disc,
  .manuscript-comment-card.is-in-margin,
  [data-flow] .editor-workspace-main > header {
    animation: none;
    transition: none;
  }
  .flow-overlay__line {
    stroke-dashoffset: 0;
  }
}
@media print {
  .flow-surface,
  .flow-dock,
  .flow-desk {
    display: none !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .flow-slip,
  .flow-post.is-arriving .flow-post__capsule {
    animation: none;
  }
}

/* A narrow desk has one foreground surface at a time. Keep ambient cards
   quiet while the writer uses a conversation, selection action or tool. */
body:has(
    .manuscript-comment-card,
    .in-flow-rail,
    .in-flow-dock,
    .twyne-quick-review-card,
    .selection-actions,
    [role="dialog"]
  )
  :is(.flow-dock, .flow-desk--dock) {
  display: none;
}

/* Zen gives a continuous manuscript more of the desk without changing its
   physical print setup or imposing monitor-wide lines. */
.page-canvas.zen-mode:not(.is-paginated) {
  width: calc(100% - 2rem);
  max-width: 74rem !important;
}

.persona-portrait[data-framing="figure"] .persona-portrait__stage {
  inset: 0;
  width: 100%;
  filter: drop-shadow(0 14px 18px rgb(0 0 0 / 0.16));
}

.persona-portrait[data-framing="figure"][data-speaking]
  .persona-portrait__stage {
  transform: scale(1.015);
}

.persona-portrait__initials {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: color-mix(in srgb, var(--pp-color) 70%, var(--color-ink));
  font: 600 calc(var(--persona-portrait-size, 64px) * 0.34) / 1
    var(--font-display);
  letter-spacing: 0.025em;
}

.persona-portrait[data-framing="figure"] .persona-portrait__initials {
  border-radius: 50%;
  background: color-mix(in srgb, var(--pp-color) 22%, var(--color-paper));
  aspect-ratio: 1;
  height: auto;
  font-size: calc(var(--persona-portrait-size, 64px) * 0.3);
}

@media (prefers-reduced-motion: reduce) {
  .persona-portrait[data-speaking="tts"] {
    animation: none;
    --pp-level: 0.6;
  }
  .persona-portrait__stage {
    transition: none;
  }
}

.persona-masthead {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  min-width: 0;
  color: var(--color-ink);
  text-align: left;
  text-transform: none;
  letter-spacing: normal;
}

.persona-masthead__identity {
  min-width: 0;
  overflow-wrap: anywhere;
}

.persona-masthead__name {
  margin: 0;
  color: inherit;
  font: 600 0.9375rem/1.3 var(--font-display);
}

.persona-masthead__role,
.persona-masthead__label {
  margin: 0.25rem 0 0;
  color: var(--color-ink-light);
  font: 400 0.75rem/1.4 var(--font-sans);
}

.persona-masthead__label {
  font-size: 0.6875rem;
}

.persona-masthead--on-color,
.persona-masthead--on-color .persona-masthead__role,
.persona-masthead--on-color .persona-masthead__label {
  color: var(--color-paper);
}

/* Scoped opt-in for existing critique headers, leaving their actions intact. */
.persona-critique-head {
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 0.625rem;
}

.persona-critique-head > .persona-masthead {
  flex: 1 1 10rem;
}

.persona-critique-head > .desk-card__stamp {
  margin-left: auto;
}

.persona-critique-head > .desk-card__byline,
.persona-critique-head > .desk-card__aside {
  flex-basis: 100%;
  min-width: 0;
}

