  height: 2rem;
  align-items: center;
  gap: 0.4rem;
  padding: 0 0.7rem;
  border: 1px solid var(--comment-color);
  border-radius: 2px;
  font-family: var(--font-typewriter);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
}
.persona-note__talk {
  background: var(--comment-color);
  color: var(--color-paper);
}
.persona-note__talk:hover {
  filter: brightness(1.08);
}
.persona-note__listen {
  background: var(--color-paper);
  color: var(--color-ink);
}
.persona-note__listen:hover,
.persona-note__listen[data-speech-status="playing"],
.persona-note__listen[data-speech-status="paused"] {
  background: color-mix(in srgb, var(--comment-color) 12%, var(--color-paper));
}
.persona-note__listen[data-speech-status="error"] {
  border-color: var(--color-accent-red);
  color: var(--color-accent-red);
}
.persona-note__strike {
  padding: 0 0.35rem;
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.persona-note__strike:hover {
  color: var(--color-vermilion);
}
.persona-note__close {
  width: 2rem;
  height: 2rem;
}
.persona-note__body {
  padding: 0.85rem 1rem;
}
.persona-note__text {
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 1rem;
  line-height: 1.6;
}
.persona-note__bubble {
  max-width: 85%;
  padding: 0.45rem 0.7rem;
  border: 1px solid var(--color-paper-3);
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.875rem;
  line-height: 1.45;
}
.persona-note__bubble--writer {
  border-radius: 6px 6px 2px 6px;
  background: var(--color-paper-soft);
}
.persona-note__bubble--persona {
  border-radius: 6px 6px 6px 2px;
}
.persona-note-typing {
  color: var(--color-ink-muted);
}
.persona-note__composer {
  flex-shrink: 0;
  padding: 0 0.75rem 0.75rem;
}
.persona-note__composer .composer:focus-within {
  border-color: var(--comment-color);
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--comment-color) 14%, transparent);
}

