/*
 * The jaw's opening, 0–1. Registered so the read-aloud keyframes can tween
 * it; Live voice writes it straight from the audio every frame instead.
 */
@property --pp-level {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.persona-portrait {
  --pp-ring: max(1.5px, calc(var(--persona-portrait-size, 64px) * 0.035));
  position: relative;
  display: block;
  flex: 0 0 var(--persona-portrait-size, 64px);
  width: var(--persona-portrait-size, 64px);
  height: var(--persona-portrait-size, 64px);
  overflow: hidden;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 38%,
    color-mix(in srgb, var(--pp-color) 16%, var(--color-paper)) 0 52%,
    color-mix(in srgb, var(--pp-color) 40%, var(--color-paper)) 100%
  );
  box-shadow:
    0 0 0 var(--pp-ring) var(--color-paper),
    0 0 0 calc(var(--pp-ring) * 2 + var(--pp-level) * var(--pp-ring) * 1.6)
      var(--pp-color),
    0 0 calc(var(--pp-level) * var(--persona-portrait-size, 64px) * 0.22)
      calc(var(--pp-ring) * 2)
      color-mix(in srgb, var(--pp-color) 45%, transparent);
  isolation: isolate;
}

.persona-portrait__stage {
  position: absolute;
  width: calc(var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35));
  aspect-ratio: 4 / 5;
  left: calc(
    50% - var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35) *
      var(--fx, 0.5)
  );
  top: calc(
    53% - var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35) * 1.25 *
      var(--fy, 0.3)
  );
  transform-origin: calc(var(--fx, 0.5) * 100%) calc(var(--fy, 0.3) * 100%);
  transition: transform 420ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.persona-portrait img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  max-width: none;
  height: 100%;
}

/* The dark of an open mouth, under the jaw, hinged on the lip line. */
.persona-portrait__mouth {
  position: absolute;
  left: calc(var(--mx) * 100%);
  top: calc(var(--my) * 100% + 0.15%);
  width: calc(var(--mw) * 62%);
  height: 1.2%;
  border-radius: 50%;
  background: radial-gradient(
    ellipse 50% 60% at 50% 35%,
    #3d1814 0 55%,
    rgb(61 24 20 / 0) 100%
  );
  translate: -50% 0;
  rotate: var(--tilt);
  scale: 1 var(--pp-level);
  transform-origin: 50% 0;
  visibility: hidden;
}

/*
 * The chin: the same engraving, cut along the lip line, feathered at the
 * cheeks and dropped along the head's own tilt. At rest it is pixel-for-pixel
 * the picture beneath, so it only appears while the editor speaks.
 */
.persona-portrait__jaw {
  position: absolute;
  inset: 0;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  clip-path: polygon(0 var(--jaw-y0), 100% var(--jaw-y1), 100% 100%, 0 100%);
  -webkit-mask-image: radial-gradient(
    ellipse calc(var(--mw) * 185%) 9% at calc(var(--mx) * 100%)
      calc(var(--my) * 100% + 3%),
    #000 55%,
    transparent 100%
  );
  mask-image: radial-gradient(
    ellipse calc(var(--mw) * 185%) 9% at calc(var(--mx) * 100%)
      calc(var(--my) * 100% + 3%),
    #000 55%,
    transparent 100%
  );
  transform: rotate(var(--tilt)) translateY(calc(var(--pp-level) * 1.1%))
    rotate(calc(var(--tilt) * -1));
  visibility: hidden;
}

.persona-portrait[data-speaking] .persona-portrait__mouth,
.persona-portrait[data-speaking] .persona-portrait__jaw {
  visibility: visible;
}

/* Read-aloud has no amplitude to follow, so the jaw keeps a speech-like,
   deliberately uneven rhythm: syllables, a stressed beat, a breath. */
.persona-portrait[data-speaking="tts"] {
  animation: pp-talk 1.7s linear infinite;
}

@keyframes pp-talk {
  0% {
    --pp-level: 0.1;
  }
  7% {
    --pp-level: 0.75;
  }
  14% {
    --pp-level: 0.2;
  }
  22% {
    --pp-level: 0.95;
  }
  29% {
    --pp-level: 0.35;
  }
  36% {
    --pp-level: 0.65;
  }
  43% {
    --pp-level: 0.12;
  }
  51% {
    --pp-level: 0.85;
  }
  58% {
    --pp-level: 0.3;
  }
  66% {
    --pp-level: 0.55;
  }
  73% {
    --pp-level: 0.08;
  }
  82%,
  100% {
    --pp-level: 0;
  }
}

.persona-portrait[data-speaking] .persona-portrait__stage {
  transform: scale(1.04);
}

@media (hover: hover) {
  .persona-portrait[data-framing="face"]:hover .persona-portrait__stage {
    transform: scale(1.06);
  }
}

/* The whole engraved editor, standing on whatever colour plate holds it. */
.persona-portrait[data-framing="figure"] {
  /* A container may size the figure for itself; inline size is the default. */
  flex-basis: var(--pp-figure-width, var(--persona-portrait-size, 64px));
  width: var(--pp-figure-width, var(--persona-portrait-size, 64px));
  height: auto;
  aspect-ratio: 4 / 5;
  overflow: visible;
  border-radius: 0;
  background: none;
  box-shadow: none;
}

import { PERSONAS } from "./personas";

const PORTRAIT_IDS = ["devil", "angel", "scholar", "editor", "reader"] as const;
export type PersonaPortraitId = (typeof PORTRAIT_IDS)[number];

export interface PersonaPortraitIdentity {
  personaId?: string | null;
  name?: string | null;
  role?: string | null;
  /** A custom persona's colour; residents always wear their own. */
  color?: string | null;
  /** A custom editor's uploaded portrait; residents keep their engravings. */
  imageUrl?: string | null;
}

/**
 * Where each engraving's face sits, as fractions of the 480×600 source:
 * the face centre (`fx`, `fy`) frames the medallion, and the lip line
 * (`mx`, `my`, `mw` wide, tilted `tilt` degrees) is where the jaw hinges
 * when the editor speaks. Measured by eye against a 5px grid.
 */
export interface PortraitFocus {
  fx: number;
  fy: number;
  mx: number;
  my: number;
  mw: number;
  tilt: number;
}

const FOCUS: Record<PersonaPortraitId, PortraitFocus> = {
  devil: { fx: 0.406, fy: 0.25, mx: 0.427, my: 0.342, mw: 0.083, tilt: -14 },
  angel: { fx: 0.54, fy: 0.29, mx: 0.585, my: 0.352, mw: 0.098, tilt: -15 },
  scholar: { fx: 0.52, fy: 0.28, mx: 0.527, my: 0.348, mw: 0.075, tilt: -8 },
  editor: { fx: 0.53, fy: 0.25, mx: 0.5, my: 0.352, mw: 0.083, tilt: 12 },
  reader: { fx: 0.55, fy: 0.29, mx: 0.5, my: 0.342, mw: 0.088, tilt: 18 },
};

/** An explicit unknown ID must never borrow a resident's face by name. */
export function resolvePersonaPortrait(input: PersonaPortraitIdentity) {
  const hasId = input.personaId != null;
  const resident = hasId
    ? PERSONAS.find((persona) => persona.id === input.personaId)
    : PERSONAS.find((persona) => persona.name === input.name);
  const portraitId = PORTRAIT_IDS.find((id) => id === resident?.id);
  const color =
    (portraitId ? resident?.color : input.color?.trim()) ||
    "var(--color-ink-light)";
  const name = input.name?.trim() || resident?.name || "Unnamed persona";
  const role = input.role?.trim() || resident?.role || "Editorial voice";
  const words = name.match(/[\p{L}\p{N}]+/gu) ?? [];
  const initials = words
    .slice(0, 2)
    .map((word) => Array.from(word)[0])
    .join("")
    .toLocaleUpperCase();

  return {
    name,
    role,
    initials: initials || "?",
    color,
    portraitId,
    focus: portraitId ? FOCUS[portraitId] : undefined,
    src: portraitId
      ? `/assets/manual/editors/${portraitId}-transparent-480.webp`
      : input.imageUrl || undefined,
    attribution: portraitId ? (hasId ? "id" : "exact-name") : "initials",
  } as const;
}

