.persona-note__reply::before {
  position: absolute;
  top: 0.2em;
  bottom: 0.2em;
  left: 0;
  width: 2px;
  border-radius: 2px;
  background: var(--comment-color);
  content: "";
  transform-origin: top;
}
.persona-note__reply--writer {
  margin-left: 1.5rem;
  color: var(--color-ink-light);
}
.persona-note__reply--writer::before {
  background: var(--color-paper-3);
}
.persona-note__guest {
  float: left;
  margin: 0.15rem 0.4rem 0 0;
}
.persona-note__reply.is-streaming {
  animation: persona-reply-enter 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
.persona-note__reply.is-streaming::before {
  animation: persona-reply-rule 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.persona-note__reply.is-streaming .comment-markdown > :last-child::after {
  display: inline-block;
  width: 0.4em;
  height: 1em;
  margin-left: 0.15em;
  border-radius: 1px;
  background: var(--comment-color);
  content: "";
  vertical-align: -0.15em;
  animation: persona-reply-caret 0.9s steps(2, jump-none) infinite;
}
.persona-note__reply.is-fresh::before {
  animation: persona-reply-settle 0.9s ease-out;
}
@keyframes persona-reply-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@keyframes persona-reply-rule {
  from {
    transform: scaleY(0);
  }
}
@keyframes persona-reply-caret {
  to {
    opacity: 0;
  }
}
@keyframes persona-reply-settle {
  from {
    box-shadow: 0 0 0 3px
      color-mix(in srgb, var(--comment-color) 35%, transparent);
  }
}
.persona-note__thinking {
  display: flex;
  height: 1.25rem;
  align-items: center;
  gap: 0.3rem;
  padding-left: 0.75rem;
}
.persona-note__thinking > span[aria-hidden] {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: 9999px;
  background: var(--comment-color);
  animation: persona-reply-dot 1.1s ease-in-out infinite;
}
.persona-note__thinking > span:nth-child(2) {
  animation-delay: 0.15s;
}
.persona-note__thinking > span:nth-child(3) {
  animation-delay: 0.3s;
}
@keyframes persona-reply-dot {
  0%,
  60%,
  100% {
    opacity: 0.35;
    transform: none;
  }
  30% {
    opacity: 1;
    transform: translateY(-3px);
  }
}
/* While the editor considers a reply, the bust leans in to think. */
.persona-note__note:has(.persona-note__thinking)
  .persona-note__bust
  .persona-portrait {
  animation: persona-bust-ponder 2.6s ease-in-out infinite;
  transform-origin: 50% 70%;
}
@keyframes persona-bust-ponder {
  0%,
  100% {
    rotate: 0deg;
  }
  50% {
    rotate: -3deg;
    translate: 0 1px;
  }
}
.persona-note__error {
  color: var(--color-vermilion);
  font-family: var(--font-typewriter);
  font-size: 0.7rem;
  line-height: 1rem;
}

/* The second box is the reply itself: focus shows on its border alone. */
.persona-note__compose {
  display: flex;
  flex-shrink: 0;
  align-items: flex-end;
  gap: 0.25rem;
  padding: 0.25rem 0.25rem 0.25rem 1rem;
  border-color: var(--color-paper-3);
  transition: border-color 0.15s ease;
}
.persona-note__compose:focus-within {
  border-color: var(--comment-color);
}
.persona-note__input {
  min-width: 0;
  max-height: 9rem;
  flex: 1;
  field-sizing: content;
  resize: none;
  padding: 0.4rem 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.9375rem;
  line-height: 1.5;
}
.persona-note__input::placeholder {
  color: var(--color-ink-muted);
}
.persona-note__send {
  display: inline-flex;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background: var(--comment-color);
  color: var(--color-paper);
  transition:
    background-color 0.15s ease,
    color 0.15s ease;
}
.persona-note__send:disabled {
  background: transparent;
  color: var(--color-ink-muted);
  cursor: default;
}
@media (prefers-reduced-motion: reduce) {
  .persona-note__menu-list,
  .persona-note__reply.is-streaming,
  .persona-note__reply.is-streaming::before,
  .persona-note__reply.is-fresh::before,
  .persona-note__thinking > span,
  .persona-note__note:has(.persona-note__thinking)
    .persona-note__bust
    .persona-portrait {
    animation: none;
  }
  .persona-note__reply.is-streaming .comment-markdown > :last-child::after {
    animation: none;
  }
}

