   rule and a small-caps mark keep it from passing for a quotation. */
.comment-markdown .quote-link--near {
  text-decoration-style: dashed;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
}
.comment-markdown .quote-near-mark {
  margin-left: 0.3em;
