}
'''
new='''/* Notices: a tinted glyph, a line or two, one action. The tone colours the
   glyph and a hairline only; the card's own colour stays the persona's. */
.persona-note__notice {
  --notice-tone: var(--color-vermilion);
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  padding: 0.4rem 0.3rem 0.4rem 0.55rem;
  border: 1px solid color-mix(in srgb, var(--notice-tone) 30%, transparent);
  border-radius: 5px;
  background: color-mix(in srgb, var(--notice-tone) 6%, var(--color-paper));
  color: var(--color-ink-light);
  font-family: var(--font-sans);
  font-size: 0.75rem;
  line-height: 1.35;
  animation: persona-notice-enter 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
.persona-note__notice[data-tone="warning"] {
  --notice-tone: var(--color-mustard);
}
.persona-note__notice-icon {
  display: inline-flex;
  height: 1.35em;
  flex-shrink: 0;
  align-items: center;
  color: var(--notice-tone);
}
.persona-note__notice-text {
  display: -webkit-box;
  min-width: 0;
  flex: 1;
  margin: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.persona-note__notice-action {
  flex-shrink: 0;
  padding: 0 0.3rem;
  border-radius: 3px;
  color: color-mix(in srgb, var(--notice-tone) 80%, var(--color-ink));
  font-weight: 600;
  line-height: 1.35rem;
  white-space: nowrap;
}
.persona-note__notice-action:hover {
  text-decoration: underline;
  text-underline-offset: 0.18em;
}
.persona-note__notice-dismiss {
  display: inline-flex;
  width: 1.35rem;
  height: 1.35rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  color: var(--color-ink-muted);
}
.persona-note__notice-dismiss svg {
  width: 10px;
  height: 10px;
}
.persona-note__notice-dismiss:hover {
  background: color-mix(in srgb, var(--notice-tone) 12%, transparent);
  color: var(--color-ink);
}
@keyframes persona-notice-enter {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
}

/* A quotation the draft does not hold keeps its words and gains a small
   mark; the reason is on hover, where the dotted rule already invites it. */
.persona-note-card .quote-unresolved {
  text-decoration-color: color-mix(in srgb, var(--color-mustard) 70%, transparent);
}
.persona-note-card .quote-unresolved::after {
  display: inline-grid;
  width: 0.95rem;
  height: 0.95rem;
  margin-left: 0.2em;
  place-items: center;
  border-radius: 9999px;
  background: var(--color-mustard);
  color: var(--color-paper);
  content: "?";
  font: 700 0.6rem/1 var(--font-sans);
  vertical-align: 0.15em;
}

/* Evidence under the note: one quiet line of chips, not a second article. */
.persona-note-card .note-evidence__label {
  font-size: 0.625rem;
}
.persona-note-card .note-evidence__near {
  padding: 0 0.4rem;
  border-radius: 9999px;
  background: color-mix(in srgb, var(--color-mustard) 16%, transparent);
  color: color-mix(in srgb, var(--color-mustard) 60%, var(--color-ink));
  font-variant: normal;
  letter-spacing: 0;
}
.persona-note-card .note-evidence__near::before {
  content: "≈ ";
}
'''
assert old in s; s=s.replace(old,new)
s=s.replace('''  .persona-note__menu-list,
  .persona-note__reply.is-streaming,''','''  .persona-note__menu-list,
  .persona-note__notice,
  .persona-note__reply.is-streaming,''')
open(p,'w').write(s)
EOF
