cat > /tmp/twyne-shots/anchor3.mjs <<'EOF'
import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";
const browser = await chromium.launch({ args: ["--disable-dev-shm-usage"] });
const page = await browser.newPage({ viewport: { width: 900, height: 760 } });
const cdp = await page.context().newCDPSession(page);
await page.goto(`http://127.0.0.1:6116/iframe.html?id=editor-selectionactions--persona-note-anchor&viewMode=story`, { waitUntil: "load", timeout: 180000 });
await page.waitForSelector(".twyne-mark-anchor img", { timeout: 180000 });
await cdp.send("DOM.enable"); await cdp.send("CSS.enable");
const { root } = await cdp.send("DOM.getDocument", { depth: -1 });
const { nodeId } = await cdp.send("DOM.querySelector", { nodeId: root.nodeId, selector: ".twyne-mark-anchor img" });
const { matchedCSSRules } = await cdp.send("CSS.getMatchedStylesForNode", { nodeId });
for (const m of matchedCSSRules) {
  const props = m.rule.style.cssProperties.filter((p) => /width|height/.test(p.name) && p.value && !p.disabled);
  if (props.length) console.log(m.rule.selectorList.text.slice(0, 90), "=>", props.map((p) => `${p.name}:${p.value}`).join("; "), m.rule.origin);
}
await browser.close();
EOF
cd /tmp/twyne-shots && env -u LD_LIBRARY_PATH node anchor3.mjs

