                  event.key === "Enter" &&
                  comment.draft.trim()
                ) {
                  event.preventDefault();
                  onCreate$();
                }
                if (event.key === "Escape") onDiscard$();
              }}
              placeholder="What belongs in the margin here?"
              class="manuscript-comment-card__textarea"
              rows={5}
